async function loadCourses(url) {
  const res = await fetch(url);

  if (!res.ok) {
    if (res.status >= 500) {
      throw new Error('서버에 문제가 있습니다 (' + res.status + ')');
    }
    throw new Error('찾지 못했습니다 (' + res.status + ')');
  }

  return res.json();
}

// 이 함수는 그대로 두세요
async function report(url) {
  try {
    const list = await loadCourses(url);
    return '성공: ' + list.map((c) => c.name).join(' · ');
  } catch (e) {
    return '실패: ' + e.message;
  }
}
